"""Operator-driven pallet tuning page; camera stream remains the existing view."""
PAGE=r'''<!doctype html><html lang="ko"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>팔레트 판정 조정</title>
<style>body{font:16px 'Noto Sans KR','Malgun Gothic','Apple SD Gothic Neo',Arial,sans-serif;background:#101820;color:#e4edf4;margin:16px}button,select,input{font:inherit;padding:7px;margin:4px}a{color:#8dd5ff}iframe{width:100%;height:680px;border:1px solid #415b70}img{width:100%;image-rendering:auto;max-width:900px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:16px}.box{padding:12px;background:#192733;border-radius:8px}label{display:block}input{width:100px}#message{white-space:pre-wrap;color:#ffdd80}table{border-collapse:collapse}td,th{padding:6px;border:1px solid #607080}.ok{color:#8fe5ad}.bad{color:#ff9d99}@media(max-width:850px){.grid{grid-template-columns:1fr}}</style>
<a href="/robot">카메라 보기</a><h2 id="title">팔레트 판정 조정</h2>
<p>① 팔레트 선택 → ② 촬영 → ③ 사진의 실제 상태 표시(각 3장) → ④ 값 제안/비교 → ⑤ 저장. 물건을 놓거나 빼는 작업은 직접 해주세요.</p>
<p>로봇 서비스는 켜고 홈 대기 상태에서 사용합니다. 작은·밝은 물건 1개, 가장자리도 확인하세요. 기존 빈 기준 사진·모델·노출·홈 설정은 바꾸지 않습니다.</p>
<div class="grid"><div class="box"><h3>기존 실시간 영상</h3><iframe src="/robot" title="현재 로봇 카메라"></iframe></div>
<div class="box"><select id="item" aria-label="팔레트"></select><button id="capture">현재 판정용 사진 촬영</button><p id="captureTime"></p>
<img id="photo" alt="왼쪽 빈 기준 / 오른쪽 이번 촬영"><p>오른쪽 사진을 확인하고 정답을 선택하세요. 이것은 빈 기준 재등록이 아닙니다.</p>
<button id="empty" disabled>이 사진은 비었음</button><button id="present" disabled>이 사진은 물건 있음</button><p id="counts"></p><div id="samples"></div>
<button id="import">저장된 정답 사진 불러오기</button><button id="clear">모은 자료 초기화</button><h3>선택 팔레트의 판정값</h3><p>값을 바꾼 뒤 ‘사진 전체 비교’를 누르세요. 큰 허용값은 작은 물건을 놓칠 수 있습니다.</p>
<details><summary>수동 파라미터 조절(필요할 때)</summary><div id="fields"></div></details><button id="suggest">모은 사진으로 값 제안</button><button id="evaluate">사진 전체 비교</button><button id="apply" disabled>선택 팔레트 YAML 저장·적용</button>
<p id="message" role="status"></p><div id="results"></div></div></div>
<script>
let info=null,pending=null,busy=false;const q=s=>document.querySelector(s),names={EMPTY:'비었음',PRESENT:'있음',UNKNOWN:'판정 불가'};
const specs={color_presence_enabled:['고정 유색 물품 모드(흰색·무채색 물건 사용 불가)',0,1,1],color_threshold:['물건 색상 차이 기준',.05,.3,.01],color_min_component_pixels:['유색 물건 최소 연결 크기',1,500,1],color_empty_component_pixels:['빈 상태 유색 잔여 크기 허용',0,499,1],precision_enabled:['정밀 비교 사용',0,1,1],pixel_threshold:['강한 픽셀 차이',5,80,1],weak_pixel_threshold:['약한 픽셀 차이',2,40,1],min_component_pixels:['물건으로 볼 최소 연결 크기',4,500,1],empty_component_pixels:['빈 상태 잔여 크기 허용(null=기존값)',1,200,1],empty_ratio:['빈 상태 변화 비율 허용',0,.02,.0005],max_color_offset:['기본 색상 보정 한도',0,30,1],adaptive_color_limit:['배경 일치 시 색상 보정 한도',0,60,1],alignment_max_px:['작은 위치 이동 탐색',0,5,1],reference_slack_px:['격자 위치 차이 허용 반경',0,3,1],min_object_width_px:['가는 차이 제거 폭(1/3/5)',1,5,2]};
function invalidate(){q('#apply').disabled=true;q('#results').replaceChildren();}
function fields(parameters){q('#fields').replaceChildren();for(const [key,[label,min,max,step]] of Object.entries(specs)){const l=document.createElement('label');l.textContent=label;const input=document.createElement('input');input.id='p_'+key;input.type=['precision_enabled','color_presence_enabled'].includes(key)?'checkbox':'number';if(input.type==='checkbox')input.checked=parameters[key];else{input.min=min;input.max=max;input.step=step;input.value=parameters[key]??'';}input.oninput=invalidate;l.append(input);q('#fields').append(l);}}
function params(){const value={};for(const key of Object.keys(specs)){const e=q('#p_'+key);value[key]=['precision_enabled','color_presence_enabled'].includes(key)?e.checked:e.value===''?null:Number(e.value);}return value;}
function render(){const item=q('#item').value;fields(info.items[item].parameters);invalidate();pending=null;q('#empty').disabled=q('#present').disabled=true;q('#photo').removeAttribute('src');q('#captureTime').textContent='';samples();}
function samples(){const rows=info.samples.filter(r=>r.item===q('#item').value);q('#counts').textContent='등록: 비었음 '+rows.filter(r=>r.label==='EMPTY').length+'장 / 있음 '+rows.filter(r=>r.label==='PRESENT').length+'장 (각 3장 이상)';q('#samples').replaceChildren();for(const [n,row] of rows.entries()){const b=document.createElement('button');b.textContent=(n+1)+' '+names[row.label];b.onclick=()=>{q('#photo').src='/pallet-tuning/image?id='+encodeURIComponent(row.id);q('#captureTime').textContent='등록한 사진 · '+new Date(row.at*1000).toLocaleTimeString();};q('#samples').append(b);}}
async function send(action,extra={}){if(busy)return;busy=true;q('#item').disabled=true;q('#message').textContent='처리 중…';q('#apply').disabled=true;try{const r=await fetch('/pallet-tuning/api',{method:'POST',headers:{'Content-Type':'application/json','X-OMX-Tuning':info.token},body:JSON.stringify({action,item:q('#item').value,...extra})});const data=await r.json();if(!r.ok)throw Error(data.error||'요청 실패');q('#message').textContent=data.message||'완료';return data;}catch(e){q('#message').textContent=e.message;}finally{busy=false;q('#item').disabled=false;}}
function report(data){q('#results').replaceChildren();const note=document.createElement('p');note.textContent='있음→비었음 오류 '+data.false_empty+'건. 사진은 단일 후보 비교이며 운영 상태는 기존 3회 연속 확인을 유지합니다.';q('#results').append(note);const table=document.createElement('table');for(const [n,row] of data.rows.entries()){const tr=document.createElement('tr');for(const text of [n+1,'정답 '+names[row.label],'판정 '+names[row.candidate],row.processing_ms.toFixed(1)+'ms',row.reason]){const td=document.createElement('td');td.textContent=text;tr.append(td);}tr.className=row.correct?'ok':'bad';table.append(tr);}q('#results').append(table);q('#apply').disabled=!data.can_save;}
q('#item').onchange=()=>{if(!busy)render();};
q('#capture').onclick=async()=>{const data=await send('capture');if(data){pending=data.id;q('#photo').src='/pallet-tuning/image?id='+encodeURIComponent(data.id);q('#captureTime').textContent='이번 촬영 · '+new Date(data.at*1000).toLocaleTimeString()+' · 후보 '+names[data.comparison.candidate];q('#empty').disabled=q('#present').disabled=false;}};
async function label(value){const data=await send('label',{id:pending,label:value});if(data){info={...data,token:info.token};pending=null;q('#empty').disabled=q('#present').disabled=true;samples();}}
q('#empty').onclick=()=>label('EMPTY');q('#present').onclick=()=>label('PRESENT');
q('#evaluate').onclick=async()=>{const data=await send('evaluate',{parameters:params()});if(data)report(data);};
q('#suggest').onclick=async()=>{const data=await send('suggest',{parameters:params()});if(data){fields(data.parameters);report(data.report);}};
q('#apply').onclick=async()=>{if(!confirm('선택 팔레트의 판정값만 저장·즉시 적용합니다. 작은 물건·밝은 물건도 확인했나요?'))return;const data=await send('apply',{parameters:params(),confirm:true});if(data){const r=await fetch('/pallet-tuning/info');info=await r.json();render();q('#message').textContent=data.message;}};
q('#import').onclick=async()=>{const data=await send('import');if(data){info={...data,token:info.token};render();q('#message').textContent=data.message;}};
q('#clear').onclick=async()=>{const data=await send('clear');if(data){info={...data,token:info.token};render();}};
(async()=>{try{const r=await fetch('/pallet-tuning/info');info=await r.json();if(!r.ok)throw Error(info.error);q('#title').textContent=info.device.toUpperCase()+' 팔레트 판정 조정';for(const item of Object.keys(info.items)){const e=document.createElement('option');e.value=e.textContent=item;q('#item').append(e);}render();}catch(e){q('#message').textContent=e.message;}})();
</script></html>'''
